# Kahoot Integration for Interactive Quizzes
import requests

KAHOOT_API_KEY = ""

def create_kahoot_quiz(title, questions):
    """Create an interactive quiz on Kahoot"""
    response = requests.post(
        "https://create.kahoot.it/rest/kahoots",
        headers={
            "Authorization": f"Bearer {KAHOOT_API_KEY}",
            "Content-Type": "application/json"
        },
        json={
            "title": title,
            "questions": questions,
            "language": "English"
        }
    )
    return response.json()
